// End-to-end tests with the real agentgateway v1.6.0 binary, the config
// generated by GenerateConfig, a real decide.Service on Postgres with the
// policy bundle, and small MCP / A2A / HTTP upstreams written here.

// --- upstreams -----------------------------------------------------------------------

// seen is one request an upstream received (headers that matter only).
type seen struct {
	Method     string // JSON-RPC method (or HTTP method for plain HTTP)
	Tool       string
	AgentID    string
	ActionID   string
	Delegation string
	Auth       string
	RouteHdrs  []string
}

type recorder struct {
	mu   sync.Mutex
	reqs []seen
}

func (r *recorder) add(s seen) {
	r.mu.Lock()
	defer r.mu.Unlock()
	r.reqs = append(r.reqs, s)
}

func (r *recorder) all() []seen {
	r.mu.Lock()
	defer r.mu.Unlock()
	return slices.Clone(r.reqs)
}

func (r *recorder) count(method string) int {
	n := 0
	for _, s := range r.all() {
		if s.Method == method {
			n++
		}
	}
	return n
}

func headersSeen(r *http.Request, method, tool string) seen {
	s := seen{Method: method, Tool: tool, AgentID: r.Header.Get(HeaderAgentID), ActionID: r.Header.Get(HeaderActionID),
		Delegation: r.Header.Get(headerDelegation), Auth: r.Header.Get("Authorization")}
	for _, h := range routeHeaders {
		if r.Header.Get(h) != "" {
			s.RouteHdrs = append(s.RouteHdrs, h)
		}
	}
	return s
}

func serve(t *testing.T, h http.Handler) string {
	t.Helper()
	lis, err := net.Listen("tcp", "127.0.0.1:0")
	if err != nil {
		t.Fatal(err)
	}
	srv := &http.Server{Handler: h, ReadHeaderTimeout: 5 * time.Second}
	go func() { _ = srv.Serve(lis) }()
	t.Cleanup(func() { _ = srv.Close() })
	return lis.Addr().String()
}

type rpcIn struct {
	JSONRPC string          `json:"jsonrpc"`
	ID      json.RawMessage `json:"id,omitempty"`
	Method  string          `json:"method"`
	Params  json.RawMessage `json:"params,omitempty"`
}

func writeRPC(w http.ResponseWriter, id json.RawMessage, result any) {
	w.Header().Set("Content-Type", "application/json")
	_ = json.NewEncoder(w).Encode(map[string]any{"jsonrpc": "2.0", "id": id, "result": result})
}

// mcpUpstream is a minimal MCP server (streamable HTTP, JSON responses)
// with a memory-server-like tool list.
func mcpUpstream(t *testing.T, rec *recorder) string {
	return serve(t, http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		if r.Method == http.MethodDelete {
			w.WriteHeader(http.StatusOK)
			return
		}
		if r.Method != http.MethodPost {
			w.WriteHeader(http.StatusMethodNotAllowed)
			return
		}
		var req rpcIn
		if err := json.NewDecoder(io.LimitReader(r.Body, 1<<20)).Decode(&req); err != nil {
			http.Error(w, "bad json", http.StatusBadRequest)
			return
		}
		var tool struct {
			Name string `json:"name"`
		}
		if req.Method == "tools/call" {
			_ = json.Unmarshal(req.Params, &tool)
		}
		rec.add(headersSeen(r, req.Method, tool.Name))
		if len(req.ID) == 0 {
			w.WriteHeader(http.StatusAccepted)
			return
		}
		switch req.Method {
		case "initialize":
			w.Header().Set("Mcp-Session-Id", "upstream-session-1")
			writeRPC(w, req.ID, map[string]any{"protocolVersion": "2025-06-18", "capabilities": map[string]any{"tools": map[string]any{}},
				"serverInfo": map[string]any{"name": "test-memory", "version": "1"}})
		case "tools/list":
			writeRPC(w, req.ID, map[string]any{"tools": []any{
				map[string]any{"name": "read_graph", "inputSchema": map[string]any{"type": "object"}},
				map[string]any{"name": "upsert_records", "inputSchema": map[string]any{"type": "object"}},
			}})
		case "tools/call":
			writeRPC(w, req.ID, map[string]any{"content": []any{map[string]any{"type": "text", "text": "executed " + tool.Name}}})
		case "ping":
			writeRPC(w, req.ID, map[string]any{})
		default:
			w.Header().Set("Content-Type", "application/json")
			_ = json.NewEncoder(w).Encode(map[string]any{"jsonrpc": "2.0", "id": req.ID, "error": map[string]any{"code": -32601, "message": "method not found"}})
		}
	}))
}

// a2aUpstream is agent_b's A2A server: it completes every task at once.
func a2aUpstream(t *testing.T, rec *recorder) string {
	return serve(t, http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		var req rpcIn
		if err := json.NewDecoder(io.LimitReader(r.Body, 1<<20)).Decode(&req); err != nil {
			http.Error(w, "bad json", http.StatusBadRequest)
			return
		}
		rec.add(headersSeen(r, req.Method, ""))
		writeRPC(w, req.ID, map[string]any{"kind": "task", "id": "task-42", "contextId": "ctx-1",
			"status":    map[string]any{"state": "completed"},
			"artifacts": []any{map[string]any{"artifactId": "a1", "parts": []any{map[string]any{"kind": "text", "text": "summary"}}}}})
	}))
}

func httpUpstream(t *testing.T, rec *recorder) string {
	return serve(t, http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		rec.add(headersSeen(r, r.Method, ""))
		w.Header().Set("Content-Type", "application/json")
		_, _ = io.WriteString(w, `{"ok":true}`)
	}))
}

// --- agentgateway process ---------------------------------------------------------------

func freeAddr(t *testing.T) string {
	t.Helper()
	l, err := net.Listen("tcp", "127.0.0.1:0")
	if err != nil {
		t.Fatal(err)
	}
	defer l.Close()
	return l.Addr().String()
}

func port(addr string) int {
	_, p, _ := net.SplitHostPort(addr)
	n, _ := strconv.Atoi(p)
	return n
}

type lockedBuf struct {
	mu sync.Mutex
	b  bytes.Buffer
}

func (l *lockedBuf) Write(p []byte) (int, error) {
	l.mu.Lock()
	defer l.mu.Unlock()
	return l.b.Write(p)
}

func (l *lockedBuf) String() string {
	l.mu.Lock()
	defer l.mu.Unlock()
	return l.b.String()
}

// startAgentgateway runs the binary with cfg until the test ends and
// returns the gateway's base URL.
func startAgentgateway(t *testing.T, bin string, cfg []byte, listen string) string {
	t.Helper()
	f := filepath.Join(t.TempDir(), "agentgateway.yaml")
	if err := os.WriteFile(f, cfg, 0o600); err != nil {
		t.Fatal(err)
	}
	cmd := exec.Command(bin, "-f", f)
	logs := &lockedBuf{}
	cmd.Stdout, cmd.Stderr = logs, logs
	if err := cmd.Start(); err != nil {
		t.Fatal(err)
	}
	exited := make(chan struct{})
	go func() { _ = cmd.Wait(); close(exited) }()
	t.Cleanup(func() {
		_ = cmd.Process.Kill()
		<-exited
		if t.Failed() {
			t.Logf("agentgateway logs:\n%s", logs.String())
		}
	})
	deadline := time.Now().Add(15 * time.Second)
	for {
		select {
		case <-exited:
			t.Fatalf("agentgateway exited at startup:\n%s", logs.String())
		default:
		}
		if c, err := net.DialTimeout("tcp", listen, 200*time.Millisecond); err == nil {
			_ = c.Close()
			break
		}
		if time.Now().After(deadline) {
			t.Fatalf("agentgateway did not listen on %s:\n%s", listen, logs.String())
		}
		time.Sleep(50 * time.Millisecond)
	}
	return "http://" + listen
}

// --- clients ------------------------------------------------------------------------------

var httpClient = &http.Client{Timeout: 10 * time.Second}

// rpcReply reads a JSON-RPC reply that may be plain JSON or one SSE event.
func rpcReply(t *testing.T, resp *http.Response) map[string]any {
	t.Helper()
	defer resp.Body.Close()
	raw, err := io.ReadAll(resp.Body)
	if err != nil {
		t.Fatal(err)
	}
	body := raw
	if strings.HasPrefix(resp.Header.Get("Content-Type"), "text/event-stream") {
		sc := bufio.NewScanner(bytes.NewReader(raw))
		for sc.Scan() {
			if v, ok := strings.CutPrefix(sc.Text(), "data:"); ok {
				body = []byte(strings.TrimSpace(v))
			}
		}
	}
	var m map[string]any
	if err := json.Unmarshal(body, &m); err != nil {
		t.Fatalf("reply is not JSON (HTTP %d): %s", resp.StatusCode, raw)
	}
	return m
}

type mcpClient struct {
	t       *testing.T
	url     string
	token   string
	session string
	id      int
	extra   map[string]string
}

func (c *mcpClient) post(method string, params any, notify bool) *http.Response {
	c.t.Helper()
	msg := map[string]any{"jsonrpc": "2.0", "method": method}
	if params != nil {
		msg["params"] = params
	}
	if !notify {
		c.id++
		msg["id"] = c.id
	}
	b, _ := json.Marshal(msg)
	req, _ := http.NewRequest(http.MethodPost, c.url, bytes.NewReader(b))
	req.Header.Set("Content-Type", "application/json")
	req.Header.Set("Accept", "application/json, text/event-stream")
	req.Header.Set("MCP-Protocol-Version", "2025-06-18")
	if c.token != "" {
		req.Header.Set("Authorization", c.token)
	}
	if c.session != "" {
		req.Header.Set("Mcp-Session-Id", c.session)
	}
	for k, v := range c.extra {
		req.Header.Set(k, v)
	}
	resp, err := httpClient.Do(req)
	if err != nil {
		c.t.Fatalf("%s: %v", method, err)
	}
	return resp
}

func (c *mcpClient) initialize() {
	c.t.Helper()
	resp := c.post("initialize", map[string]any{"protocolVersion": "2025-06-18", "capabilities": map[string]any{},
		"clientInfo": map[string]any{"name": "e2e", "version": "1"}}, false)
	if resp.StatusCode != http.StatusOK {
		b, _ := io.ReadAll(resp.Body)
		resp.Body.Close()
		c.t.Fatalf("initialize: HTTP %d %s", resp.StatusCode, b)
	}
	c.session = resp.Header.Get("Mcp-Session-Id")
	if r := rpcReply(c.t, resp); r["result"] == nil {
		c.t.Fatalf("initialize: %v", r)
	}
	n := c.post("notifications/initialized", nil, true)
	n.Body.Close()
}

// callTool returns the tool result text and whether it is an error result
// (or a JSON-RPC error message).
func (c *mcpClient) callTool(name string) (string, bool) {
	c.t.Helper()
	r := rpcReply(c.t, c.post("tools/call", map[string]any{"name": name, "arguments": map[string]any{}}, false))
	if e, ok := r["error"].(map[string]any); ok {
		return fmt.Sprint(e["message"]), true
	}
	res, _ := r["result"].(map[string]any)
	isErr, _ := res["isError"].(bool)
	var text []string
	for _, c := range asList(res["content"]) {
		if m, ok := c.(map[string]any); ok {
			text = append(text, fmt.Sprint(m["text"]))
		}
	}
	return strings.Join(text, " "), isErr
}

func a2aPost(t *testing.T, url, token, body string, extra map[string]string) (*http.Response, []byte) {
	t.Helper()
	req, _ := http.NewRequest(http.MethodPost, url, strings.NewReader(body))
	req.Header.Set("Content-Type", "application/json")
	if token != "" {
		req.Header.Set("Authorization", token)
	}
	for k, v := range extra {
		req.Header.Set(k, v)
	}
	resp, err := httpClient.Do(req)
	if err != nil {
		t.Fatal(err)
	}
	defer resp.Body.Close()
	b, _ := io.ReadAll(resp.Body)
	return resp, b
}

// --- the test --------------------------------------------------------------------------------

func TestEndToEndAgentgateway(t *testing.T) {
	bin := agentgatewayBinary(t)
	mcpRec, a2aRec, httpRec := &recorder{}, &recorder{}, &recorder{}
	mcpAddr := mcpUpstream(t, mcpRec)
	a2aAddr := a2aUpstream(t, a2aRec)
	httpAddr := httpUpstream(t, httpRec)

	listen := freeAddr(t)
	spec := GenSpec{
		Port:          port(listen),
		AdminAddr:     freeAddr(t),
		StatsAddr:     freeAddr(t),
		ReadinessAddr: freeAddr(t),
		MCP:           []MCPRoute{{Name: "memory", PathPrefix: "/mcp/memory", Server: "memory", URL: "http://" + mcpAddr + "/mcp"}},
		A2A:           []A2ARoute{{Name: "agent-b", PathPrefix: "/a2a/agent_b", Agent: "agent_b", Backend: a2aAddr}},
		HTTP:          []HTTPRoute{{Name: "example", Domain: "api.example.com", Backend: httpAddr}},
	}
	cfg := spec.FortikConfig()
	cfg.Listen = ""
	f := newFixture(t, cfg)
	spec.Callout = f.addr
	gen, err := GenerateConfig(spec)
	if err != nil {
		t.Fatal(err)
	}
	base := startAgentgateway(t, bin, gen, listen)

	f.putProfile(t, "agent_a", "mcp", `{"servers":{"memory":["*"]}}`)
	f.putProfile(t, "agent_a", "a2a", `{"may_delegate_to":["agent_b"],"max_depth":3}`)
	f.putProfile(t, "agent_a", "http", `{"external":"allowlist","allowed_domains":["api.example.com"]}`)

	// --- MCP ---
	mc := &mcpClient{t: t, url: base + "/mcp/memory", token: bearer("agent_a"),
		extra: map[string]string{HeaderAgentID: "agent_c", MetaRouteMCP: "evil"}}
	mc.initialize()

	t.Run("MCP read tool allowed", func(t *testing.T) {
		mc.t = t
		text, isErr := mc.callTool("read_graph")
		if isErr || text != "executed read_graph" {
			t.Fatalf("read_graph: %q isError=%v", text, isErr)
		}
		var got *seen
		for _, s := range mcpRec.all() {
			if s.Tool == "read_graph" {
				got = &s
			}
		}
		if got == nil {
			t.Fatal("read_graph did not reach the MCP server")
		}
		if got.AgentID != "agent_a" || !strings.HasPrefix(got.ActionID, "act_") {
			t.Fatalf("identity at the MCP server: %+v (client sent x-fortik-agent-id: agent_c)", *got)
		}
		if got.Auth != "" || len(got.RouteHdrs) > 0 || got.Delegation != "" {
			t.Fatalf("token or route headers leaked upstream: %+v", *got)
		}
		if n := f.count(t, `SELECT count(*) FROM actions WHERE action_id=$1 AND system='mcp' AND verb='READ' AND decision='allow' AND target->>'tool'='read_graph'`, got.ActionID); n != 1 {
			t.Fatal("read_graph not recorded with the injected action id")
		}
	})

	t.Run("MCP write tool held", func(t *testing.T) {
		mc.t = t
		before := mcpRec.count("tools/call")
		// An unmapped write tool: EXECUTE, held until it is mapped.
		text, isErr := mc.callTool("upsert_records")
		if !isErr || !strings.Contains(text, "hold") || !strings.Contains(text, "action_id=") {
			t.Fatalf("upsert_records: %q isError=%v", text, isErr)
		}
		if mcpRec.count("tools/call") != before {
			t.Fatal("a held tool call reached the MCP server")
		}
		if n := f.count(t, `SELECT count(*) FROM held_actions h JOIN actions a USING (action_id) WHERE a.system='mcp' AND a.target->>'tool'='upsert_records' AND a.verb='EXECUTE'`); n != 1 {
			t.Fatalf("held_actions rows: %d", n)
		}
		// The session still works after a refusal.
		if text, isErr := mc.callTool("read_graph"); isErr {
			t.Fatalf("read after refusal: %s", text)
		}
	})

	t.Run("MCP without a token", func(t *testing.T) {
		anon := &mcpClient{t: t, url: base + "/mcp/memory", extra: map[string]string{HeaderAgentID: "agent_a"}}
		resp := anon.post("initialize", map[string]any{"protocolVersion": "2025-06-18", "capabilities": map[string]any{},
			"clientInfo": map[string]any{"name": "e2e", "version": "1"}}, false)
		r := rpcReply(t, resp)
		if r["error"] == nil {
			t.Fatalf("unauthenticated initialize: %v", r)
		}
	})

	// --- A2A ---
	a2aURL := base + "/a2a/agent_b"
	send := a2aBody("message/send", sendParams)

	var tokenAtB, hopAction string
	t.Run("A2A delegation allowed, token reaches agent_b", func(t *testing.T) {
		resp, body := a2aPost(t, a2aURL, bearer("agent_a"), send, map[string]string{HeaderAgentID: "agent_c", MetaRouteAgent: "agent-x"})
		if resp.StatusCode != http.StatusOK || !strings.Contains(string(body), "task-42") {
			t.Fatalf("message/send: HTTP %d %s", resp.StatusCode, body)
		}
		got := a2aRec.all()
		if len(got) != 1 {
			t.Fatalf("agent_b requests: %+v", got)
		}
		s := got[0]
		if s.AgentID != "agent_a" || s.Auth != "" || len(s.RouteHdrs) > 0 {
			t.Fatalf("at agent_b: %+v", s)
		}
		// The hop may already be closed (agent_b answered with a completed
		// task), so read the chain from the token's claims; Verify must refuse
		// it once the hop is closed (a closed hop's token is revoked).
		claims := decodeClaims(t, s.Delegation)
		if !slices.Equal(claims.Chain, []string{"agent_a", "agent_b"}) {
			t.Fatalf("chain: %v", claims.Chain)
		}
		tokenAtB = s.Delegation
		hopAction = s.ActionID
		// agent_b answered with a completed task: the observer closes the hop.
		deadline := time.Now().Add(5 * time.Second)
		for f.count(t, `SELECT count(*) FROM delegations WHERE action_id=$1 AND status='closed'`, s.ActionID) != 1 {
			if time.Now().After(deadline) {
				t.Fatal("hop not closed after the completed task passed through agentgateway")
			}
			time.Sleep(50 * time.Millisecond)
		}
		if strings.Contains(f.diaryBodies(t), s.Delegation) {
			t.Fatal("delegation token in the Diary")
		}
		if _, err := f.deleg.Verify(context.Background(), s.Delegation, "agent_b"); !errors.Is(err, delegation.ErrRevokedToken) {
			t.Fatalf("token of a closed hop must be revoked, got %v", err)
		}
	})

	// UC1 through agentgateway: agent_b acts for agent_a, forwarding its
	// token, on an MCP server agent_a itself may not write to.
	t.Run("delegated MCP call checked against the originating agent", func(t *testing.T) {
		if tokenAtB == "" {
			t.Skip("needs the delegation subtest")
		}
		f.putProfile(t, "agent_b", "mcp", `{"servers":{"memory":["*"]}}`)
		f.putProfile(t, "agent_a", "mcp", `{"servers":{"memory":["search_nodes"]}}`)
		bc := &mcpClient{t: t, url: base + "/mcp/memory", token: bearer("agent_b"), extra: map[string]string{delegation.Header: tokenAtB}}
		bc.initialize()
		before := mcpRec.count("tools/call")
		// The hop closed when agent_b completed the task: its token is stale
		// and refused outright (POL-604), never reaching the MCP server.
		if text, isErr := bc.callTool("read_graph"); !isErr || !strings.Contains(text, "POL-604") {
			t.Fatalf("stale delegation token: %q isError=%v", text, isErr)
		}
		// Reopen the hop (agent_b still working for agent_a): now the bypass rule applies.
		if _, err := f.pool.Exec(context.Background(), `UPDATE delegations SET status='open', closed_at=NULL WHERE action_id=$1`, hopAction); err != nil {
			t.Fatal(err)
		}
		text, isErr := bc.callTool("read_graph")
		if !isErr || !strings.Contains(text, "POL-601") {
			t.Fatalf("delegated read_graph: %q isError=%v", text, isErr)
		}
		if mcpRec.count("tools/call") != before {
			t.Fatal("the bypass attempt reached the MCP server")
		}
		if n := f.count(t, `SELECT count(*) FROM alerts WHERE kind='delegation_bypass'`); n < 1 {
			t.Fatal("no delegation_bypass alert")
		}
	})

	t.Run("A2A refused", func(t *testing.T) {
		before := len(a2aRec.all())
		resp, body := a2aPost(t, a2aURL, bearer("agent_c"), send, nil)
		if resp.StatusCode != http.StatusForbidden || !strings.Contains(string(body), "POL-020") || !strings.Contains(string(body), `"jsonrpc":"2.0"`) {
			t.Fatalf("agent_c: HTTP %d %s", resp.StatusCode, body)
		}
		resp, body = a2aPost(t, a2aURL, "", send, map[string]string{HeaderAgentID: "agent_a"})
		if resp.StatusCode != http.StatusUnauthorized {
			t.Fatalf("no token: HTTP %d %s", resp.StatusCode, body)
		}
		resp, body = a2aPost(t, a2aURL, bearer("agent_a"), "["+send+","+send+"]", nil)
		if resp.StatusCode < 400 {
			t.Fatalf("batch: HTTP %d %s", resp.StatusCode, body)
		}
		resp, body = a2aPost(t, a2aURL, bearer("agent_a"), send, map[string]string{delegation.Header: "forged"})
		if resp.StatusCode != http.StatusForbidden {
			t.Fatalf("forged inbound token: HTTP %d %s", resp.StatusCode, body)
		}
		if len(a2aRec.all()) != before {
			t.Fatal("a refused A2A request reached agent_b")
		}
	})

	// --- HTTP egress ---
	t.Run("HTTP egress", func(t *testing.T) {
		req, _ := http.NewRequest(http.MethodGet, base+"/v1/items", nil)
		req.Host = "api.example.com"
		req.Header.Set("Authorization", bearer("agent_a"))
		req.Header.Set(HeaderAgentID, "agent_c")
		resp, err := httpClient.Do(req)
		if err != nil {
			t.Fatal(err)
		}
		resp.Body.Close()
		if resp.StatusCode != http.StatusOK {
			t.Fatalf("GET: HTTP %d", resp.StatusCode)
		}
		got := httpRec.all()
		if len(got) != 1 || got[0].AgentID != "agent_a" || got[0].Auth != "" {
			t.Fatalf("at the HTTP upstream: %+v", got)
		}
	})

	// --- callout down: everything fails closed ---
	t.Run("callout down fails closed", func(t *testing.T) {
		mc.t = t
		f.stop()
		mcpBefore, a2aBefore := mcpRec.count("tools/call"), len(a2aRec.all())
		if text, isErr := mc.callTool("read_graph"); !isErr {
			t.Fatalf("MCP with the callout down: %q", text)
		}
		resp, body := a2aPost(t, a2aURL, bearer("agent_a"), send, nil)
		if resp.StatusCode < 400 {
			t.Fatalf("A2A with the callout down: HTTP %d %s", resp.StatusCode, body)
		}
		if mcpRec.count("tools/call") != mcpBefore || len(a2aRec.all()) != a2aBefore {
			t.Fatal("a request reached an upstream while the callout was down")
		}
	})
}

// decodeClaims reads a delegation token's claims without verifying it (the
// tests verify separately).
func decodeClaims(t *testing.T, tok string) delegation.Claims {
	t.Helper()
	payload, _, ok := strings.Cut(tok, ".")
	if !ok {
		t.Fatalf("malformed delegation token")
	}
	raw, err := base64.RawURLEncoding.DecodeString(payload)
	if err != nil {
		t.Fatal(err)
	}
	var c delegation.Claims
	if err := json.Unmarshal(raw, &c); err != nil {
		t.Fatal(err)
	}
	return c
}
